import {PROMISE} from './pages.mjs';
import {hydrate,filterRecords,allocate,selectPortfolio,parseCSV,validateResearchRows,STAGES,WEIGHTS} from './engine.mjs';
import {icon} from './icons.mjs';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,d=1)=>Number.isFinite(v)?v.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
const cash=v=>v.toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0});
const pct=v=>n(v*100,1)+'%';
const cashExact=v=>v.toLocaleString('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2});
const count=v=>v.toLocaleString('en-US');
const colors={'AI & Data':'#588c75','FinTech':'#c7a66d','Enterprise SaaS':'#789daf','Health & Education':'#b6a5c7','Hardware':'#d69b7c','Commerce':'#8798bb','Consumer & Social':'#bc8fa8','Other':'#91b5a7'};
const short={'AI & Data':'AI','FinTech':'FI','Enterprise SaaS':'SA','Health & Education':'HE','Hardware':'HW','Commerce':'CO','Consumer & Social':'CS','Other':'OT'};
const views=['overview','why','explore','portfolio','research','methodology'];
let stored={};try{stored=JSON.parse(localStorage.getItem('venturelens-yc-v2')||'{}');}catch{}
const defaults={budget:100000,country:'all',stage:'all',domain:'all',cashRate:.1,cap:.25,positions:10,selection:'score'};
const state={view:views.includes(location.hash.slice(1))?location.hash.slice(1):'overview',mandate:{...defaults,...stored.mandate},plan:[],compare:new Set(),page:1,researchIndex:0,researchOrigin:'repository',live:{mode:'snapshot',llmConfigured:false},busy:false,stress:0};
const policyValid=m=>Number.isFinite(m.budget)&&m.budget>=1000&&m.budget<=10000000&&m.cashRate>=0&&m.cashRate<=.5&&m.cap>=.05&&m.cap<=1&&Number.isInteger(m.positions)&&m.positions>=1&&m.positions<=10;
if(!policyValid(state.mandate))state.mandate={...defaults};
state.filters={...state.mandate,search:'',sort:'score'};
let rows=[],byUid=new Map(),data,domains=[],countries=[],research=[],toastTimer;
function persist(){try{localStorage.setItem('venturelens-yc-v2',JSON.stringify({mandate:state.mandate,plan:state.plan}));}catch{}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
const candidates=()=>filterRecords(rows,state.mandate);
const planRows=()=>state.plan.map(id=>byUid.get(id)).filter(Boolean);
const allocation=()=>allocate(planRows(),state.mandate.budget,state.mandate.cashRate,state.mandate.cap);
function opts(values,current,all='All'){return `<option value="all" ${current==='all'?'selected':''}>${all}</option>`+values.map(v=>`<option value="${esc(v)}" ${current===v?'selected':''}>${esc(v)}</option>`).join('');}
const optsSimple=(values,current)=>values.map(([v,t])=>`<option value="${v}" ${Number(current)===Number(v)?'selected':''}>${t}</option>`).join('');
function heading(eyebrow,title,text,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subheading">${text}</p></div>${action}</div>`;}
function render(){const content=({overview,explore,portfolio,research:researchPage,why:whyPage,methodology})[state.view]();$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#overview" aria-label="VentureLens home"><span class="brand-icon">v</span><div class="brand-copy"><div class="brand-name">VentureLens<span style="color:#90a77c">.</span></div><div class="brand-sub">A founder's next investment</div></div></a><div class="workspace-label">Investment workspace</div><nav class="nav" aria-label="Main navigation">${[['overview','grid','Overview'],['why','leaf','Why VentureLens'],['explore','search','Explore startups'],['portfolio','wallet','Portfolio planner'],['research','book','Research desk'],['methodology','shield','Methodology']].map(([v,i,t])=>`<button data-nav="${v}" class="${v===state.view?'active':''}" title="${t}" ${v===state.view?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="side-note">${icon('leaf',20)}<br><strong>Your next chapter, in focus.</strong><p>The team's model. The evidence behind it. A purpose for your capital.</p></div><div class="profile"><span class="avatar">AM</span><div><div class="profile-name">Alex Morgan</div><div class="profile-caption">Exited founder · demo client</div></div><button data-action="mandate" aria-label="Edit investment mandate">${icon('edit',14)}</button></div></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb">VentureLens <span style="padding:0 10px;color:#b8c3b3">/</span><b>${({overview:'Investment overview',why:'Our investment approach',explore:'Startup screening',portfolio:'Portfolio allocation',research:'News & sentiment',methodology:'Model & sources'})[state.view]}</b></div><div class="top-right"><span class="dataset-pill"><i class="dot"></i>Team model snapshot</span><span class="avatar" style="width:29px;height:29px;font-size:9px">AM</span></div></header><main class="main" id="main" tabindex="-1">${content}${footer()}</main></div>${state.compare.size?`<div class="comparison-tray"><span>${state.compare.size} of 3 records selected</span><button class="text-btn" data-action="clear-compare">Clear</button><button class="btn small" data-action="compare" ${state.compare.size<2?'disabled':''}>Compare ${icon('arrow',12)}</button></div>`:''}`;}
function navigate(view){state.view=view;history.replaceState(null,'','#'+view);render();window.scrollTo({top:0,behavior:'instant'});}
function draft(){return allocate(selectPortfolio(rows,state.mandate),state.mandate.budget,state.mandate.cashRate,state.mandate.cap);}
function donut(a){const invested=a.invested/a.budget,total=396;return `<div class="donut-wrap"><svg class="donut" viewBox="0 0 160 160" role="img" aria-label="${n(invested*100,0)} percent proposed investments and ${n(a.cashWeight*100,0)} percent cash"><g fill="none" stroke-width="11" transform="rotate(-90 80 80)"><circle cx="80" cy="80" r="63" stroke="#e0e6d5"/><circle cx="80" cy="80" r="63" stroke="#2d7658" stroke-dasharray="${Math.max(0,invested*total-3)} ${total}"/></g><text x="80" y="76" text-anchor="middle" fill="#1c3329" font-size="23" font-weight="650">${cash(a.budget/1000)}k</text><text x="80" y="95" text-anchor="middle" fill="#8d9a85" font-size="9">YOUR CAPITAL</text></svg><div class="allocation-key"><div><i class="legend-swatch" style="background:#2d7658"></i>Investments<strong>${pct(invested)}</strong></div><div><i class="legend-swatch" style="background:#b8c7a5"></i>Cash<strong>${pct(a.cashWeight)}</strong></div></div></div>`;}
function portfolio(){const a=allocation(),m=state.mandate;return heading('A purpose for every dollar','Your capital plan, explained.',`Allocate ${cash(m.budget)} using the team’s score-and-scale policy, with explicit cash and position limits.`,`<div class="portfolio-top"><button class="btn" data-action="mandate">${icon('edit',12)} Mandate</button><button class="btn primary" data-action="generate">${icon('layers',14)} ${a.positions.length?'Rebuild draft':'Generate draft'}</button></div>`)+`<div class="budget-strip"><div class="budget-item"><span>Proposed investments</span><strong>${cash(a.invested)}</strong><p>${a.positions.length} ${a.positions.length===1?'position':'positions'} · weighted by score × scale</p></div><div class="budget-item"><span>Retained cash</span><strong>${cash(a.cash)}</strong><p>${pct(m.cashRate)} minimum · residuals remain in cash</p></div><div class="budget-item"><span>Capital limit</span><strong>${cash(a.budget)}</strong><p>${pct(m.cap)} maximum per position</p></div></div><div class="notice">${icon('shield',15)} &nbsp; An illustrative capital plan. Positions use the team’s scores and your ${cash(m.budget)} capital limit. No orders execute. Historical company names are supplied. Current operating status, investment access, financials, and terms require verification.</div><div class="portfolio-grid"><div><section class="panel"><div class="panel-head"><div><h2>Your proposed positions <span style="color:#8b9a80">${a.positions.length} / ${m.positions}</span></h2><p>${esc(m.country==='all'?'All countries':m.country)} · ${esc(m.stage==='all'?'All stages':m.stage)} · ${esc(m.domain==='all'?'All domains':m.domain)} · ${m.selection==='domain'?'One leader per domain':'Top scores overall'}</p></div>${a.positions.length?'<button class="clear-btn" data-action="clear-plan">Clear draft</button>':''}</div>${a.positions.length?`<div class="holdings">${a.positions.map(p=>`<div class="holding"><span class="sector-icon" style="background:${colors[p.record.domain]}20;color:${colors[p.record.domain]}">${short[p.record.domain]}</span><div><button class="record-link" data-detail="${p.record.uid}" style="font-size:12px">${esc(p.record.id)}</button><div class="record-sub">${esc(p.record.domain)} · ${esc(p.record.stage)} bucket · ${pct(p.amount/a.budget)}</div></div><strong class="holding-amount">${cashExact(p.amount)}</strong><button class="icon-btn" data-add="${p.record.uid}" aria-label="Remove ${esc(p.record.id)}">${icon('close',14)}</button></div>`).join('')}<div class="holding"><span class="sector-icon">$</span><div><strong style="font-size:12px">Cash reserve</strong><div class="record-sub">${pct(a.cashWeight)} of the portfolio</div></div><strong class="holding-amount">${cashExact(a.cash)}</strong><span></span></div></div><div style="padding:0 23px 22px;display:flex;justify-content:space-between;align-items:center"><span class="record-sub">${cash(a.invested+a.cash)} accounted for</span><button class="btn small" data-action="export">${icon('download',12)} Export plan</button></div>`:`<div class="empty">${icon('layers',28)}<h3>The team’s model, your capital.</h3><p>Generate up to ${m.positions} score-and-scale positions. The policy retains at least ${pct(m.cashRate)} in cash and caps each position at ${pct(m.cap)}.</p><button class="btn primary" data-action="generate">Generate draft allocation ${icon('arrow',13)}</button></div>`}</section><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>The reasoning behind the allocation</h2>${icon('book',17)}</div><div style="padding:0 23px 20px"><div class="step-list"><div class="step"><span class="step-n">01</span><div><h3>Filter the candidate universe</h3><p>Keep historically Operating records, then apply Alex’s country, domain, and stage preferences.</p></div></div><div class="step"><span class="step-n">02</span><div><h3>Combine score with funding and backer scale</h3><p>Rank by the YC screening model. Multiply the score by the logarithmic funding/backer scale, then apply the 4% floor and position cap.</p></div></div><div class="step"><span class="step-n">03</span><div><h3>Preserve capital when limits bind</h3><p>With fewer candidates, excess capital remains in cash. A budget does not force an investment.</p></div></div></div></div></section></div><div><section class="panel" style="margin-bottom:22px"><div class="panel-head"><h2>Portfolio mix</h2><span class="chip">Illustrative</span></div><div style="padding:0 20px 22px">${donut(a)}<div class="alloc-line"><span>Largest position</span><strong>${pct(Math.max(0,...a.positions.map(p=>p.amount/a.budget)))}</strong></div><div class="alloc-line"><span>Domains represented</span><strong>${new Set(a.positions.map(p=>p.record.domain)).size}</strong></div><p class="record-sub" style="margin-top:12px">Position limits control one kind of concentration. They do not make private startup investing low risk.</p></div></section><section class="panel"><div class="scenario"><h2>Investment-loss scenario</h2><p class="record-sub" style="margin-top:8px">Uniform loss on initial positions. No return forecast.</p><div style="margin:23px 0"><label for="stress" style="font-size:11px">Loss on invested capital <strong id="stress-label">${state.stress}%</strong></label><input style="width:100%;accent-color:var(--green);margin-top:12px" id="stress" type="range" min="0" max="100" step="5" value="${state.stress}"></div><div class="scenario-total"><span>Illustrative remaining value</span><strong id="stress-total">${cash(a.cash+a.invested*(1-state.stress/100))}</strong></div><p class="scenario-explain">Cash remains at face value. This arithmetic illustration excludes fees, taxes, dilution, timing, and liquidity. At a 100% investment loss, only the retained cash remains.</p></div></section></div></div>`;}
function parseSources(r){try{const s=JSON.parse(r.source_items_json||'[]');return Array.isArray(s)?s.filter(i=>{try{return ['http:','https:'].includes(new URL(i.url).protocol);}catch{return false;}}):[];}catch{return [];}}
function showDetail(uid){const r=byUid.get(uid);if(!r)return;const d=$('#detail-dialog');d.innerHTML=detailMarkup(r);if(!d.open)d.showModal();}
function add(uid){const r=byUid.get(uid),index=state.plan.indexOf(uid);if(index>=0)state.plan.splice(index,1);else{if(!filterRecords([r],state.mandate).length){toast('This record is outside your mandate. Edit the mandate to include it.');return;}if(state.plan.length>=state.mandate.positions){toast('The draft has reached your position limit. Remove a position first.');return;}state.plan.push(uid);}persist();render();if($('#detail-dialog').open)$('#detail-dialog').innerHTML=detailMarkup(r);toast('Draft updated. Capital is recalculated within the position cap.');}
function mandate(){const m=state.mandate,d=$('#mandate-dialog');d.innerHTML=`<div class="dialog-head"><div><div class="eyebrow">Alex’s mandate</div><h2 id="mandate-title">A plan shaped around the client.</h2><p>Exited founder · five-year horizon · high risk tolerance</p></div><button class="icon-btn" data-close="mandate-dialog" aria-label="Close mandate">${icon('close',20)}</button></div><form class="dialog-body" id="mandate-form"><div class="mandate-fields"><div class="field"><label for="budget">Investment budget (USD)</label><input id="budget" name="budget" type="number" min="1000" max="10000000" step="100" required value="${m.budget}"></div><div class="field"><label for="m-country">Country</label><select id="m-country" name="country">${opts(countries,m.country,'All countries')}</select></div><div class="field"><label for="m-domain">Domain</label><select id="m-domain" name="domain">${opts(domains,m.domain,'All domains')}</select></div><div class="field"><label for="m-stage">Estimated stage bucket</label><select id="m-stage" name="stage">${opts(STAGES,m.stage,'All stages')}</select></div><div class="field"><label for="selection">Selection policy</label><select id="selection" name="selection"><option value="score" ${m.selection!=='domain'?'selected':''}>Top scores overall (team default)</option><option value="domain" ${m.selection==='domain'?'selected':''}>One leader per domain (optional)</option></select></div><div class="field"><label for="positions">Maximum positions</label><select id="positions" name="positions">${optsSimple([1,2,3,5,6,8,10].map(v=>[v,String(v)]),m.positions)}</select></div><div class="field"><label for="reserve">Minimum cash</label><select id="reserve" name="cashRate">${optsSimple([[0,'0%'],[.1,'10%'],[.2,'20%'],[.3,'30%'],[.5,'50%']],m.cashRate)}</select></div><div class="field"><label for="cap">Maximum position</label><select id="cap" name="cap">${optsSimple([[.1,'10%'],[.15,'15%'],[.25,'25%'],[.35,'35%'],[.5,'50%'],[1,'100%']],m.cap)}</select></div></div><div class="notice">The team’s default policy is ten score-and-scale positions, at least 10% cash, a 4% minimum position, and a 25% maximum position. Changing the mandate clears the existing draft. Stage buckets come from disclosed funding, not verified round labels. If caps prevent full allocation, excess stays in cash.</div><p class="subheading">This demo assumes taxes, emergency needs, and core savings are already provided for. Real startup access, eligibility, liquidity, and terms require verification.</p><div class="mandate-footer"><button type="button" class="btn" data-close="mandate-dialog">Cancel</button><button class="btn primary" type="submit">Save mandate ${icon('arrow',12)}</button></div></form>`;d.showModal();}
function exportPlan(){const a=allocation(),result={title:'VentureLens historical YC investment planning scenario',generatedAt:new Date().toISOString(),mandate:state.mandate,provenance:data.provenance,positions:a.positions.map(p=>({companyId:p.record.id,domain:p.record.domain,stage:p.record.stage,country:p.record.country,score:p.record.score,estimatedStage:true,weight:p.amount/a.budget,allocationUSD:p.amount,peerFundingReferenceUSDMillions:p.record.fairValue,scaleFactor:p.scale,allocationScore:p.allocationScore})),cashUSD:a.cash,totalUSD:a.budget,notes:['Historical YC snapshot, not current investment offerings. Funding stages are inferred buckets.','Historical identities are supplied. Verify current operating status, financials, access and terms.','No investment has executed.']};const u=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const el=document.createElement('a');el.href=u;el.download='venturelens-investment-plan.json';el.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Draft plan exported.');}
async function refreshResearch(){if(state.live.mode!=='python'||state.busy)return;const r=research[state.researchIndex];state.busy=true;render();try{const response=await fetch('/api/research',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({company:r.company_name})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Research failed');const accepted=validateResearchRows([result]);if(!accepted.length)throw new Error('The research response did not contain valid sentiment data.');research[state.researchIndex]=result;toast('Research refreshed. Check the returned analysis engine and source coverage.');}catch(error){toast(error.message);}finally{state.busy=false;render();}}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-detail]');if(!b||b.disabled)return;if(b.dataset.nav){navigate(b.dataset.nav);return;}if(b.dataset.close){$('#'+b.dataset.close).close();return;}if(b.dataset.detail!==undefined){showDetail(b.dataset.detail);return;}if(b.dataset.add!==undefined){add(b.dataset.add);return;}if(b.dataset.page){state.page=Number(b.dataset.page);render();return;}if(b.dataset.research!==undefined){state.researchIndex=Number(b.dataset.research);render();return;}switch(b.dataset.action){case 'mandate':mandate();break;case 'generate':state.plan=selectPortfolio(rows,state.mandate).map(r=>r.uid);persist();render();toast('Draft generated from the team model. No investment has executed.');break;case 'clear-plan':state.plan=[];persist();render();break;case 'reset':state.filters={...state.mandate,search:'',sort:'score'};state.page=1;render();break;case 'compare':compare();break;case 'clear-compare':state.compare.clear();render();break;case 'export':exportPlan();break;case 'import-research':$('#research-upload').click();break;case 'refresh-research':refreshResearch();break;}});
document.addEventListener('change',async e=>{if(e.target.dataset.filter){state.filters[e.target.dataset.filter]=e.target.value;state.page=1;render();}if(e.target.dataset.compare!==undefined){const uid=e.target.dataset.compare;if(e.target.checked){if(state.compare.size===3){e.target.checked=false;toast('Compare up to three records.');return;}state.compare.add(uid);}else state.compare.delete(uid);render();}if(e.target.id==='research-upload'){const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw new Error('Please import a research CSV smaller than 2 MB.');const parsed=parseCSV(await file.text()),valid=validateResearchRows(parsed);if(!valid.length)throw new Error('Use the sentiment output CSV with company_name and overall_sentiment_score columns.');research=valid;state.researchOrigin='import';state.researchIndex=0;navigate('research');toast(`${valid.length} research records imported. Original files were not changed.`);}catch(error){toast(error.message);}e.target.value='';}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const position=e.target.selectionStart;state.filters.search=e.target.value;state.page=1;render();$('#search').focus();$('#search').setSelectionRange(position,position);}if(e.target.id==='stress'){state.stress=Number(e.target.value);$('#stress-label').textContent=state.stress+'%';const a=allocation();$('#stress-total').textContent=cash(a.cash+a.invested*(1-state.stress/100));}});
document.addEventListener('submit',e=>{if(e.target.id!=='mandate-form')return;e.preventDefault();const f=new FormData(e.target),m={budget:Number(f.get('budget')),country:f.get('country'),stage:f.get('stage'),domain:f.get('domain'),selection:f.get('selection')||'score',cashRate:Number(f.get('cashRate')),cap:Number(f.get('cap')),positions:Number(f.get('positions'))};if(!policyValid(m)){toast('Please check the mandate values.');return;}state.mandate=m;state.filters={...m,search:'',sort:'score'};state.plan=[];state.page=1;persist();$('#mandate-dialog').close();render();toast('Mandate updated. Generate a fresh draft to apply the policy.');});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('circle[data-detail]')){e.preventDefault();showDetail(e.target.dataset.detail);}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(views.includes(v)){state.view=v;render();}});
try{const response=await fetch('/data/model.json');if(!response.ok)throw new Error('Model snapshot not found');data=await response.json();rows=hydrate(data);byUid=new Map(rows.map(r=>[r.uid,r]));countries=[...new Set(rows.map(r=>r.country))].sort();domains=[...new Set(rows.map(r=>r.domain))].sort();research=validateResearchRows(data.research);state.plan=(Array.isArray(stored.plan)?stored.plan:[]).filter(uid=>byUid.has(uid)&&filterRecords([byUid.get(uid)],state.mandate).length).slice(0,state.mandate.positions);render();fetch('/api/status').then(r=>r.ok&&r.headers.get('content-type')?.includes('application/json')?r.json():null).then(s=>{if(s?.mode==='python'){state.live=s;if(state.view==='research')render();}}).catch(()=>{});}catch(error){$('#app').innerHTML='<div class="boot"><h1>The model snapshot could not load.</h1><p>Generate web/data/model.json with python web/build_data.py, then reload.</p><button class="btn" onclick="location.reload()">Reload</button></div>';console.error(error);}

function footer(){return `<footer class="source-note">YC cohorts 2005–2014 · ${count(rows.length)} scored companies · ${count(candidates().length)} match your mandate · Historical snapshot<br>Source: <a class="foot-link" href="https://github.com/WalkerSimpson1/Hackathon" target="_blank" rel="noopener">WalkerSimpson1 / Hackathon</a>. Original data: Alice Corona, SeedDB, Crunchbase and AngelList, <a class="foot-link" href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a>. Derived scores and groupings follow the team model.<br>Names and Operating labels are historical. Stage buckets are inferred. Funding comparisons do not measure valuation or growth. Verify current activity and investment access. <button class="text-btn" data-nav="methodology">Model & limitations ${icon('arrow',11)}</button></footer>`;}
function uspStrip(){return `<section class="usp-strip" aria-label="Our investment angle"><div><div class="eyebrow">Our angle</div><h2>A reason for every dollar.</h2><p>Your domain preferences shape the shortlist. Visible model signals explain each candidate. Explicit limits shape the allocation.</p></div><button class="btn" data-nav="why">Why VentureLens ${icon('arrow',13)}</button></section>`;}
function overview(){const c=candidates(),a=draft(),m=state.mandate;return heading('VentureLens / For the founder’s next chapter','Your experience. A considered investment plan.','Named companies, transparent screening, and a clear purpose for your $100,000.',`<button class="btn" data-action="mandate">${icon('edit',13)} Edit mandate</button>`)+`<section class="hero"><div class="hero-copy"><div class="eyebrow">Meet Alex. Founder turned angel investor.</div><h2>A founder’s next investment.<br><em>A reason for every dollar.</em></h2><p>Alex built a business and exited in 2026. Now he has ${cash(m.budget)} to back other founders. VentureLens helps him compare the evidence and plan how much to commit.</p><button class="btn" data-nav="why">See Alex’s investment approach ${icon('arrow',14)}</button></div><div class="hero-mini">VentureLens / Founder to investor</div></section><div class="metrics">${[['Investment capital',cash(m.budget),'Dedicated high-risk sleeve','wallet'],['Eligible in this view',count(c.length),'Historically Operating · mandate filters','search'],['Model positions',String(a.positions.length),`${pct(m.cap)} cap · 4% floor · ${pct(m.cashRate)} min cash`,'layers'],['Source universe',String(data.summary.rawCompanies),`${rows.length} scored · YC cohorts 2005–2014`,'book']].map(([l,v,t,i])=>`<div class="metric"><div class="metric-label">${l}${icon(i,15)}</div><div class="metric-value">${v}</div><div class="metric-note">${t}</div></div>`).join('')}</div>${uspStrip()}<div class="notice warn">Historical demonstration: Operating status is as recorded, and stage labels are funding-based estimates. No current round, investability or measured growth has been verified.</div><div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>Leaders in each domain</h2><p>Highest score in each model domain within your mandate.</p></div><button class="text-btn" data-nav="explore">Explore ${icon('arrow',12)}</button></div><div class="domain-leaders">${[...new Map([...c].reverse().map(r=>[r.domain,r])).values()].sort((a,b)=>b.score-a.score).map(r=>`<button data-detail="${r.uid}" class="domain-leader"><span class="sector-icon" style="background:${colors[r.domain]}20;color:${colors[r.domain]}">${short[r.domain]}</span><span><strong>${esc(r.id)}</strong><small>${esc(r.domain)} · ${esc(r.stage)} bucket</small></span><b>${n(r.score*100,1)}</b></button>`).join('')||'<p class="empty">No candidates match your mandate.</p>'}</div></section><section class="panel"><div class="panel-head"><div><h2>Where the money could go</h2><p>${m.selection==='domain'?'One leader per domain scenario':'Latest team selection and allocation rule'}</p></div>${icon('wallet',17)}</div><div class="allocation-body">${donut(a)}<div class="alloc-line"><span>Proposed investments</span><strong>${cash(a.invested)}</strong></div><div class="alloc-line"><span>Retained cash</span><strong>${cash(a.cash)}</strong></div><div class="alloc-line"><span>Total capital</span><strong>${cash(a.budget)}</strong></div><button class="btn" data-nav="portfolio">Review the capital plan ${icon('arrow',13)}</button></div></section></div><div class="section-heading"><div><h2>The model’s leading candidates</h2><p>Exact scores from the latest YC model. Each candidate has an evidence panel.</p></div><button class="text-btn" data-nav="explore">Explore all ${icon('arrow',12)}</button></div><div class="opportunity-grid">${c.slice(0,3).map(card).join('')}</div>`;}
function card(r){return `<article class="opportunity"><div class="opp-top"><span class="sector-icon" style="background:${colors[r.domain]}20;color:${colors[r.domain]}">${short[r.domain]}</span><span class="score"><strong>${n(r.score*100,1)}</strong> / 100</span></div><button class="record-link" data-detail="${r.uid}">${esc(r.id)}</button><div class="record-sub">${esc(r.country)} · YC ${r.cohort} ${esc(r.session)}</div><p class="company-description">${esc(r.description)}</p><div class="tag-row"><span class="tag">${esc(r.domain)}</span><span class="tag">${esc(r.stage)} bucket</span></div><div class="opp-numbers"><div><span>Known funding, $m</span><strong>${n(r.funding,3)}</strong></div><div><span>Non-YC backers</span><strong>${n(r.investors,0)}</strong></div></div><div class="opp-footer"><button class="text-btn" data-detail="${r.uid}">Why this company? ${icon('arrow',12)}</button><button class="add-btn ${state.plan.includes(r.uid)?'added':''}" data-add="${r.uid}" aria-label="${state.plan.includes(r.uid)?'Remove':'Add'} ${esc(r.id)} to draft">${icon(state.plan.includes(r.uid)?'check':'plus',14)}</button></div></article>`;}
function whyPage(){const a=draft();return heading('Our USP / A founder’s next investment','A reason for every dollar.','An investment planning workspace designed around an exited founder’s decision.')+`<section class="positioning"><div class="eyebrow">Who we serve</div><h2>Alex knows how to build a company.<br>Now he needs a process for backing several.</h2><p class="positioning-body">After his exit, Alex sets aside ${cash(state.mandate.budget)} for high-risk startup investing. He wants to support other founders in domains he understands, compare unfamiliar opportunities, and avoid letting one attractive story consume his whole budget.</p><p class="positioning-promise">${PROMISE}</p><button class="btn primary" data-action="mandate">Shape Alex’s mandate ${icon('arrow',13)}</button></section><div class="usp-proof-list">${[
 ['01','The founder shapes the search','Choose domain, country and estimated stage. The shortlist changes with the mandate. Company names and business descriptions let Alex apply his own operating judgement.','explore','Explore the shortlist'],
 ['02','Each score opens into its evidence','Inspect all five component contributions. Distinguish the model’s funding/backer proxy from facts about revenue, valuation and current growth.','methodology','Understand the maths'],
 ['03','The plan explains the dollars',`The current scenario proposes ${cash(a.invested)} across ${a.positions.length} companies and retains ${cash(a.cash)}. Score × scale determines sizes within explicit bounds.`,'portfolio','Review the allocation'],
 ['04','Missing evidence stays visible','The tool shows historical status, inferred stages and unanswered investment-access questions. The research desk accepts sourced research without inventing missing financials.','research','Review research readiness']
 ].map(([i,t,p,v,action])=>`<section class="usp-proof"><span>${i}</span><div><h2>${t}</h2><p>${p}</p><button class="text-btn" data-nav="${v}">${action} ${icon('arrow',12)}</button></div></section>`).join('')}</div><section class="panel method-card"><h2>The investment proposal has boundaries</h2><p>Team default: top ten scores overall, 10% cash, 4% minimum per selected position and a 25% cap. Size each holding with the score and logarithmic funding/backer scale. The optional one-per-domain policy changes the selected set and recalculates the same allocation rule.</p><p>The angle is a concrete workflow for this founder: preferences become a shortlist, evidence explains its scores, and explicit rules produce the dollar plan. Alex can explain his choices to himself: why each company fits, how much he would commit, and which evidence still needs checking.</p><a class="btn" href="/VentureLens_USP_and_Investment_Story.pptx" download>Download the presentation ${icon('download',13)}</a></section>`;}
function explore(){const result=filterRecords(rows,state.filters),pages=Math.max(1,Math.ceil(result.length/20));state.page=Math.min(state.page,pages);const start=(state.page-1)*20;return heading('Named YC companies / Latest team model','Find the candidates in your domain.','Filter the historically Operating companies. Scores and estimated stage buckets follow evaluation.py.')+`<div class="filters"><div class="field search-field"><label for="search">Search companies</label><input id="search" type="search" value="${esc(state.filters.search)}" placeholder="Name, business description, city…"></div><div class="field"><label for="domain">Domain</label><select id="domain" data-filter="domain">${opts(domains,state.filters.domain,'All domains')}</select></div><div class="field"><label for="stage">Estimated stage bucket</label><select id="stage" data-filter="stage">${opts(STAGES,state.filters.stage,'All buckets')}</select></div><div class="field"><label for="country">Country as recorded</label><select id="country" data-filter="country">${opts(countries,state.filters.country,'All countries')}</select></div><button class="btn" data-action="reset">Reset</button></div><div class="filter-summary"><span><strong>${count(result.length)} companies</strong> · Select up to 3 to compare</span><span><label for="sort">Sort by </label><select id="sort" data-filter="sort" style="border:0;background:transparent;font-size:11px"><option value="score" ${state.filters.sort==='score'?'selected':''}>Screening score</option><option value="funding" ${state.filters.sort==='funding'?'selected':''}>Known funding</option><option value="backers" ${state.filters.sort==='backers'?'selected':''}>Backer count</option><option value="gap" ${state.filters.sort==='gap'?'selected':''}>Funding proxy gap</option></select></span></div><div class="table-wrap"><table><thead><tr><th>Compare</th><th>Company</th><th>Domain / estimated stage</th><th class="numeric">Funding, $m</th><th class="numeric">Backers</th><th class="numeric">Score / 100</th><th>Add</th></tr></thead><tbody>${result.slice(start,start+20).map(r=>`<tr><td><input type="checkbox" data-compare="${r.uid}" ${state.compare.has(r.uid)?'checked':''} aria-label="Compare ${esc(r.id)}"></td><td><button class="record-link" data-detail="${r.uid}">${esc(r.id)}</button><div class="record-sub">${esc(r.country)} · YC ${r.cohort}</div></td><td><div class="row-domain"><i style="background:${colors[r.domain]}"></i>${esc(r.domain)}</div><div class="record-sub">${esc(r.stage)} funding bucket</div></td><td class="numeric">${n(r.funding,3)}</td><td class="numeric">${n(r.investors,0)}</td><td class="numeric"><span class="score"><strong>${n(r.score*100,1)}</strong></span></td><td><button class="add-btn ${state.plan.includes(r.uid)?'added':''}" data-add="${r.uid}" aria-label="${state.plan.includes(r.uid)?'Remove':'Add'} ${esc(r.id)} to draft">${icon(state.plan.includes(r.uid)?'check':'plus',13)}</button></td></tr>`).join('')}</tbody></table>${!result.length?'<div class="empty"><h3>No matching companies</h3><p>Broaden the filters or clear the search.</p><button class="btn" data-action="reset">Reset filters</button></div>':''}<div class="screening-caption">The model scores ${rows.length} of the ${data.summary.rawCompanies} source records after its funding/backer filters. Operating labels are historical. Funding buckets do not confirm a current round. The proxy model does not measure revenue growth.</div></div><div class="pagination"><span>${result.length?start+1:0}–${Math.min(start+20,result.length)} of ${count(result.length)}</span><div><button class="btn small" data-page="${state.page-1}" ${state.page===1?'disabled':''}>Previous</button><span style="padding:7px">${state.page} / ${pages}</span><button class="btn small" data-page="${state.page+1}" ${state.page>=pages?'disabled':''}>Next</button></div></div>`;}
function methodology(){return heading('The latest YC model','The maths and its assumptions.','The repository’s calculations, expressed in terms of what this historical dataset actually contains.')+`<div class="method-grid"><section class="panel method-card"><h2>The source and the shortlist</h2><p>${data.summary.rawCompanies} named companies from YC cohorts 2005–2014. The loader keeps ${rows.length} with positive recorded funding and at least one non-YC backer. Of these, ${data.summary.operatingScored} have a historically Operating label and enter the candidate universe.</p><p>The extraction date is unknown. Model categories follow the first matching keyword group. Stage labels are estimates from funding totals. Missing information does not establish a poor business.</p><a class="btn small" href="https://github.com/WalkerSimpson1/Hackathon/blob/${esc(data.provenance.sourceCommit)}/evaluation.py" target="_blank" rel="noopener">Read this model revision ${icon('external',12)}</a></section><section class="panel method-card"><h2>Five components, one score</h2>${[['Funding/backer comparison','valuation'],['Cohort-age proxy','survival'],['Investor & team backing','backing'],['Domain preference','tech'],['Estimated stage preference','stage']].map(([t,k])=>`<div class="weight-row"><div>${t}</div><span>${WEIGHTS[k]}%</span></div>`).join('')}<p>Score = 100 × (0.35V + 0.25S + 0.20B + 0.10T + 0.10E). Weights are chosen assumptions. This is a screening score, not an estimated success probability or risk-adjusted return.</p></section><section class="panel method-card"><h2>The funding comparison is a proxy</h2><p>Recorded funding ÷ non-YC backers gives dollars raised per backer. The model compares it with a median for the domain and estimated stage when at least ten peers exist, falling back to domain, stage or overall peers.</p><p>Reference funding = backers × peer funding per backer. Gap = reference funding ÷ recorded funding − 1. The model maps this gap to 0–1 using its 5th/95th percentile bounds.</p><p>The repository calls these fields Fair_Value and Upside. The inputs are funding and backer counts. They cannot establish company value, cheapness or prospective return.</p></section><section class="panel method-card"><h2>Age, backing and preferences</h2><p>Cohort age = min((2015 − YC year) ÷ 5, 1). The code derives 2015 from its latest cohort + 1. This is not survival verified through 2026.</p><p>Backing = 0.7 × min(tier-1 backers ÷ 3, 1) + 0.3 × min(founders ÷ 3, 1). The investor list uses exact names. Missing founder count receives a neutral component. Gender does not enter the score.</p><p>Domain preferences range from 1.00 for AI & Data to 0.33 for Consumer & Social. Stage preferences range from 1.00 for the Seed bucket to 0.25 for Pre-IPO. These are model choices, not measured sector returns.</p></section><section class="panel method-card"><h2>How the dollar amounts work</h2><p>For selected companies, funding factor F = ln(1 + funding in $k) ÷ its selected-company mean. Backer factor I = ln(1 + backers) ÷ its selected-company mean. Scale = √(F × I). Allocation score = screening score × scale.</p><p>Distribute 90% of the default $100,000 in proportion to allocation scores, with a 4% floor and 25% cap. Round to whole dollars, correcting the first eligible holding within bounds. Fewer candidates can leave additional cash.</p><p>The ten-company default matches the repository’s saved dollar allocations exactly. Filtered scenarios use bounded redistribution so caps still hold when few companies qualify. The website’s optional domain-leader policy is a separate selection scenario.</p></section><section class="panel method-card"><h2>Funding-based stage buckets</h2><p>Seed: below $2m. Series A: $2m to below $15m. Series B: $15m to below $50m. Series C+: $50m to below $200m. Pre-IPO: $200m or more.</p><p>These labels come from cumulative disclosed funding, not actual round records. Undisclosed funding contributes zero in the team parser, so totals are incomplete. Four source strings have ambiguous decimal punctuation, which the parser can misread. These issues require source verification.</p><p>Revenue, valuation, cash runway and current operating status are missing. The model cannot identify the fastest-growing companies or confirm current angel access.</p></section><section class="panel method-card"><h2>AI explains sourced evidence</h2><p>Code performs the scoring and allocation. The repository’s research module can analyse news/community coverage using a configured model, with a local VADER fallback.</p><p>This hosted version contains the named YC model and accepts research CSV imports. It has no live research service configured. The ten-company result file replaces the old unrelated sentiment sample. Imported coverage retains its actual engine label and never changes the financial score automatically.</p></section><section class="panel method-card"><h2>What Alex receives</h2><p>A shortlist shaped by his mandate, a visible breakdown of its proxy scores, dollar allocations with explicit limits, and a clear record of missing evidence.</p><p>He can compare companies, choose the optional domain-leader scenario, inspect a total-loss illustration, and export his plan. No investment executes. Five years is the client’s planning horizon and does not guarantee an exit or liquidity.</p><p>Original data attribution: Alice Corona, aggregated from SeedDB, Crunchbase and AngelList, CC BY-SA 4.0. The website preserves the team’s scores and marks derived classifications as estimates.</p></section></div><details class="source-note"><summary>Source revision and file fingerprint</summary><p>${esc(data.provenance.sourceCommit)}<br>${esc(data.provenance.scoredFileSHA256)}</p></details>`;}
function evidence(r){return `${r.id} scores ${n(r.score*100,1)} / 100 in the team’s YC screen. The file records ${cash(r.funding*1e6)} in disclosed funding and ${n(r.investors,0)} non-YC backers. The peer benchmark is ${cash(r.peerMultiple*1e6)} per backer, producing a funding reference of ${cash(r.fairValue*1e6)}. This is a funding/backer comparison, not an estimate of company value or investment return.`;}
function safeURL(value){try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:null;}catch{return null;}}
function detailMarkup(r){const url=safeURL(r.website);return `<div class="dialog-head"><div><div class="eyebrow">Historical YC company / Team model evidence</div><h2 id="detail-title">${esc(r.id)}</h2><p>${esc(r.domain)} · ${esc(r.stage)} funding bucket · ${esc(r.country)}</p></div><button class="icon-btn" data-close="detail-dialog" aria-label="Close evidence">${icon('close',21)}</button></div><div class="dialog-body"><p class="detail-description">${esc(r.description)}</p><div class="detail-stats">${[['Recorded funding, USD',cash(r.funding*1e6)],['Non-YC backers',n(r.investors,0)],['Founder count',n(r.founders,0)],['YC cohort',String(r.cohort)]].map(([l,v])=>`<div class="detail-stat"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><h3>What contributes to ${n(r.score*100,1)} points?</h3><div style="margin-top:12px">${[['valuation','Funding/backer comparison'],['survival','Cohort-age proxy'],['backing','Investor & team backing'],['tech','Domain preference'],['stage','Estimated stage preference']].map(([k,t])=>`<div class="component-row"><span>${t} <small>${WEIGHTS[k]}% weight · input ${n(r.parts[k],3)}</small></span><div><i style="width:${Math.max(0,r.parts[k]*100)}%"></i></div><strong>${n(r.parts[k]*WEIGHTS[k],1)}</strong></div>`).join('')}</div><div class="memo"><h3>${icon('book',15)} Why the model selected this candidate</h3><p>${esc(evidence(r))}</p><h3 style="margin-top:18px">Questions before committing capital</h3><p>Is the company currently operating and raising? What are its verified stage, latest revenue trajectory, valuation and deal terms? Can Alex access a suitable ticket? The source supplies historical company names but no verified current investment opportunity.</p><span class="memo-label">This explanation is a deterministic summary of evaluation.py output. It is not a live LLM response.</span></div><details class="record-evidence"><summary>Original funding and category evidence</summary><p><strong>Funding string:</strong> ${esc(r.fundingRaw)}</p><p><strong>Categories:</strong> ${esc(r.categories)}</p><p><strong>Founders as recorded:</strong> ${esc(r.founderNames)}</p><p><strong>Backers as recorded:</strong> ${esc(r.investorNames)}</p></details><div class="detail-footer"><span class="muted">${url?`<a class="foot-link" href="${esc(url)}" target="_blank" rel="noopener">Website as recorded ${icon('external',11)}</a>`:'No website recorded'}<br>Historical record, current status unverified</span><button class="btn primary" data-add="${r.uid}">${icon(state.plan.includes(r.uid)?'check':'plus',14)} ${state.plan.includes(r.uid)?'Remove from draft':'Add to draft'}</button></div></div>`;}
function compare(){const chosen=[...state.compare].map(u=>byUid.get(u));if(chosen.length<2)return;const d=$('#compare-dialog');d.innerHTML=`<div class="dialog-head"><div><div class="eyebrow">Compare historical YC evidence</div><h2 id="compare-title">The candidates, side by side.</h2><p>Stage labels are funding buckets. Screening scores are heuristic.</p></div><button class="icon-btn" data-close="compare-dialog" aria-label="Close comparison">${icon('close',20)}</button></div><div class="dialog-body"><div class="compare-grid" style="grid-template-columns:repeat(${chosen.length},1fr)">${chosen.map(r=>`<div class="compare-card"><h3>${esc(r.id)}</h3><p class="record-sub">${esc(r.domain)} · ${esc(r.stage)} bucket<br>${esc(r.country)}</p>${[['Screening score',n(r.score*100,1)],['Recorded funding',cash(r.funding*1e6)],['Non-YC backers',n(r.investors,0)],['Founder count',n(r.founders,0)],['Tier-1 backers',n(r.tier1,0)],['YC cohort',String(r.cohort)]].map(([l,v])=>`<div class="compare-stat"><span>${l}</span><strong>${v}</strong></div>`).join('')}<button class="btn small" style="margin-top:15px" data-detail="${r.uid}">Inspect evidence ${icon('arrow',12)}</button></div>`).join('')}</div><p class="source-note">No revenue history establishes measured growth. Verify current status, open-round access and investment terms before acting.</p></div>`;d.showModal();}
function researchPage(){
 const r=research[state.researchIndex]||research[0],sources=r?parseSources(r):[];
 const numeric=(record,key)=>record&&record[key]!==null&&record[key]!==undefined&&String(record[key]).trim()!==''&&Number.isFinite(Number(record[key]))?Number(record[key]):null;
 const signed=v=>v===null?'Not supplied':(v>=0?'+':'')+n(v,3);
 const company=numeric(r,'company_sentiment_score'),founder=numeric(r,'founder_sentiment_score'),overall=numeric(r,'overall_sentiment_score');
 const coverage=key=>numeric(r,key)===null?'Not recorded':n(numeric(r,key),0);
 const blend=company!==null&&founder!==null?.6*company+.4*founder:null;
 const founderCoverage=(numeric(r,'founder_news_count')||0)+(numeric(r,'founder_social_count')||0);
 return heading('Research desk / Company and founder sentiment','See the sentiment behind the shortlist.','Select a company to inspect its saved scores and coverage. These scores do not change portfolio weights.',`<button class="btn" data-action="import-research">${icon('download',13)} Import research CSV</button>`)+
 `<div class="notice">${research.length?`${research.length} saved company results loaded. Scores range from −1 (negative) through 0 (neutral) to +1 (positive). A score is not a probability or expected return.`:'No saved results are loaded. Import an output CSV with company_name, Company_ID or Company and overall_sentiment_score.'}</div>`+
 (r?`<div class="research-layout"><section class="panel research-list"><div class="panel-head"><div><h2>Company results</h2><p>Overall scores · labels as supplied</p></div></div>${research.map((v,i)=>`<button class="research-choice ${i===state.researchIndex?'selected':''}" data-research="${i}" aria-pressed="${i===state.researchIndex}"><span><strong>${esc(v.company_name)}</strong><small>${esc(v.sentiment_label||'Label not supplied')}</small></span><span class="sentiment-tag">${signed(numeric(v,'overall_sentiment_score'))}</span></button>`).join('')}</section>
 <section class="panel"><div class="panel-head"><div><h2>${esc(r.company_name)}</h2><p>${state.researchOrigin==='import'?'Imported research':'Repository research snapshot'} · Generation date not supplied</p></div><span class="chip">${esc(r.sentiment_label||'Label not supplied')}</span></div><div class="research-body">
 <div class="sentiment-scores">${[['Overall sentiment',overall,'Combined company and founder signal'],['Company sentiment',company,'Model score for company coverage'],['Founder sentiment',founder,founderCoverage?'Model score for founder coverage':'Founder coverage absent or unrecorded']].map(([label,value,note])=>`<div class="sentiment-score"><span>${label}</span><strong>${signed(value)}</strong><small>${note}</small></div>`).join('')}</div>
 <div class="sentiment-scale" role="img" aria-label="Overall sentiment ${signed(overall)} on a scale from negative one to positive one"><div class="sentiment-track"><i style="left:${overall===null?50:(overall+1)*50}%"></i></div><div><span>−1 Negative</span><span>0 Neutral</span><span>+1 Positive</span></div></div>
 <div class="memo"><h3>How to read this result</h3><p>${company!==null&&founder!==null?`The saved run combines 60% company sentiment and 40% founder sentiment: 0.60 × ${signed(company)} + 0.40 × ${signed(founder)} = ${signed(blend)}.${Math.abs(blend-overall)>.0015?' The supplied overall score differs from this calculation; review the imported run.':''}`:'This import does not supply both component scores. The overall result cannot be reconstructed here.'}</p><p>Read the score alongside the coverage below. Zero can reflect missing evidence. The label is supplied by the run and may differ from a fixed threshold rule.</p></div>
 <h3 style="margin:24px 0 10px">Coverage recorded by the run</h3><div class="coverage-grid">${[['Company news','company_news_count'],['Company community posts','company_social_count'],['Founder news','founder_news_count'],['Founder community posts','founder_social_count']].map(([label,key])=>`<div><span>${label}</span><strong>${coverage(key)}</strong></div>`).join('')}</div><p class="record-sub" style="margin:12px 0 20px">Total recorded items: ${coverage('total_coverage_count')}. Counts do not establish source independence, reliable identity matching or confidence.</p>
 <div class="alloc-line"><span>Reported analysis engine</span><strong>${esc(r.analysis_engine||'Not supplied')}</strong></div><p class="record-sub">This engine label comes from the saved output. No model call runs when you open this page.</p>
 <details class="record-evidence"><summary>Evidence and refresh limits</summary><p>${sources.length?'The supplied source URLs are listed below. Their contents have not been independently verified.':'This export has no source URLs or generation timestamp. Headlines and personal reputation claims are not presented as verified evidence.'}</p><p>Founder/company name matches need review. A neutral founder score does not establish a clean background or a leadership track record.</p>${sources.map(i=>`<p><a class="foot-link" href="${esc(i.url)}" target="_blank" rel="noopener">${esc(i.title||i.url)}</a></p>`).join('')}</details>
 </div></section></div>`:'')+
 `<section class="panel method-card" style="margin-top:22px"><h2>Using the Research desk</h2><p>Choose a company on the left. Compare its overall, company and founder scores, then check how much relevant coverage supports them. The saved sentiment is a research input for human review, separate from the screening score and the dollar allocation.</p><p>To refresh, run the team’s Python research script and use <strong>Import research CSV</strong>. The import accepts company_name, Company_ID or Company plus overall_sentiment_score. Cash rows are excluded.</p><code class="research-command">python SentimentAnalysis/analyze_sentiment.py -i venturelens_portfolio_output.csv -f Founders.csv -o venturelens_portfolio_output_sentiment.csv</code><p>Run this from the repository folder with its Python dependencies and your team’s model configuration. Without a usable model key the script uses its local NLP fallback. This hosted page displays saved or imported results and does not perform live API calls.</p></section>`;
}

document.addEventListener('change',e=>{if(e.target.id==='research-choice'){state.researchIndex=Number(e.target.value);render();}});
